interface Mode { handle(ctx: Connection): void }
class Connection {
  private mode: Mode;
  constructor(m: Mode) { this.mode = m }
  request() { this.mode.handle(this) }
  setMode(m: Mode) { this.mode = m }
}
class Open implements Mode {
  handle(ctx: Connection) { console.log('sending'); ctx.setMode(new Closed()) }
}
class Closed implements Mode {
  handle(ctx: Connection) { console.log('cannot send') }
}

enum OrderStatus { New, Paid, Shipped }
class Order {
  status: OrderStatus = OrderStatus.New
  process() {
    switch (this.status) {
      case OrderStatus.New: this.pay(); break;
      case OrderStatus.Paid: this.ship(); break;
      case OrderStatus.Shipped: this.complete(); break;
    }
  }
  pay() {}
  ship() {}
  complete() {}
}

