interface DoorState { open(d: Door): void; close(d: Door): void }
class Door {
  private state: DoorState
  constructor(s: DoorState) { this.state = s }
  open() { this.state.open(this) }
  close() { this.state.close(this) }
  setState(s: DoorState) { this.state = s }
}
class OpenState implements DoorState { open(d: Door) { console.log('already open') } close(d: Door) { d.setState(new ClosedState()) } }
class ClosedState implements DoorState { open(d: Door) { d.setState(new OpenState()) } close(d: Door) { console.log('already closed') } }

